(88, 'Bourg-en-Bresse. Les Estivales de Brou tirent la sonnette d’alarme', 'https://www.leprogres.fr/culture-loisirs/2024/04/13/les-estivales-de-brou-tirent-la-sonnette-d-alarme', NULL, 'L’association des Estivales de Brou a tenu son assemblée générale, jeudi, à la Maison de la culture et de la citoyenneté. L’occasion d’alerter sur ...', 'data:image/jpeg;base64,', 'data:image/png;base64,', '2025-02-06 14:48:19', '2025-02-06 14:48:19', '2024-04-13 16:51:14', 1, 1, NULL);
