(89, 'Estivales de Brou : Ode à l’art lyrique - Bourg-en-Bresse', 'https://bourg-en-bresse.magville.fr/sortir/estivales-de-brou-bourg/', NULL, 'Nouvelle édition des estivales de Brou, découvrez la programmation de cette année, Récital lyrique, chants traditionnels, musique sacrée...', 'data:image/jpeg;base64,', 'data:image/png;base64,', '2025-02-06 14:48:50', '2025-02-06 14:48:50', '2024-06-13 06:00:00', 1, 1, NULL);
INSERT INTO `Article` (`id`, `title`, `link`, `subtitle`, `content`, `image`, `favicon`, `created_at`, `updated_at`, `Creation_article`, `is_published`, `user_id`, `event_id`) VALUES
(90, 'Bourg-en-Bresse - 32e édition des Estivales de Brou : un enthousiasme sans cesse renouvelé • La Voix de l\'Ain', 'https://www.lavoixdelain.fr/bourg-en-bresse-32e-edition-des-estivales-de-brou-un-enthousiasme-sans-cesse-renouvele/', NULL, 'Début juillet, l\'art lyrique sera de nouveau à l\'honneur à Brou. Un lieu royal qui lui convient si bien. Un art trop souvent méjugé, mais d\'une si grande richesse.', '/homepage/description.jpg', 'data:image/png;base64,', '2025-02-06 14:49:29', '2025-02-06 14:49:29', '2023-04-18 15:30:00', 1, 1, NULL);
