INSERT INTO `Event` (`id`, `title`, `subtitle`, `description`, `event_date`, `created_at`, `location`, `max_participants`, `is_public`, `user_id`, `brochure_path`, `booking_link`) VALUES
(77, 'Orchestre des chenapans', 'Les aventures musicales des espiègles', 'L\'Orchestre des Chenapans est un ensemble musical innovant qui réunit des artistes passionnés. Leur répertoire éclectique mélange des genres variés, allant de la musique classique aux influences contemporaines. Avec une approche ludique et interactive, ils souhaitent toucher un large public, notamment les jeunes. Leur énergie et leur créativité transforment chaque performance en un moment unique et mémorable.', '2025-02-28 12:48:00', '2025-02-06 14:51:09', '5bis rue d\'ypres 01000 Bourg-en-Bresse', 110, 1, 18, '/uploads/brochures/1738850582483-Brochure_(1).pdf', 'https://www.fnacspectacles.com/event/les-estivales-de-brou-2025-eglise-de-brou-bourg-en-bresse-19643267/'),
(79, 'Festival ÀLAFOLIE !', 'Concerts en plein air au 2ᵉ cloître du Monastère royal de Brou.', 'Chaque samedi soir du 20 juillet au 31 août 2024, le festival propose des concerts variés allant de la chanson française au jazz, en passant par l’électro et le blues, dans un cadre historique unique.', '2025-04-17 11:28:00', '2025-02-06 15:30:20', '6 boulevard de brou 01000 Bourg-en-Bresse', 300, 1, 18, '/uploads/brochures/1738852712471-Brochure_(1).pdf', 'https://www.monastere-de-brou.fr/agenda/2024/festival-alafolie'),
(80, 'Les Estivales de Brou 2025', 'Festival de musique lyrique et sacrée dans l’église du Monastère royal de Brou.', 'Du 5 au 11 juillet 2025, assistez à des concerts de musique lyrique et sacrée interprétés par des artistes de renommée internationale, dans le cadre majestueux de l’église du Monastère royal de Brou.', '2023-01-11 11:47:00', '2025-02-06 15:49:12', '6 boulevard de brou 01000 Bourg-en-Bresse', 300, 1, 18, '/uploads/brochures/1738916003885-Cours_CI_CD.pdf', 'https://www.jds.fr/manifestations/festival/les-estivales-de-brou-2025-767021_A'),
(81, 'Exposition “Fous de Dymphne, étonnantes histoires d’une peinture flamande”', 'Exposition temporaire au Monastère royal de Brou.', 'Du 5 avril au 22 juin 2025, découvrez une exposition dédiée à une peinture flamande du XVe siècle, offrant un aperçu unique de l’art et de l’histoire de cette époque.', '2025-04-05 12:00:00', '2025-02-06 15:52:14', '6 boulevard de brou 01000 Bourg-en-Bresse', 200, 1, 18, '/uploads/brochures/1738853533950-Brochure_(1).pdf', 'https://www.monastere-de-brou.fr/'),
(82, 'Festival ÀLAFOLIE ! 2024', 'Concerts en plein air au 2ᵉ cloître du Monastère royal de Brou.', 'Chaque samedi soir du 20 juillet au 31 août 2024, le festival a proposé des concerts variés allant de la chanson française au jazz, en passant par l’électro et le blues, dans un cadre historique unique.', '2024-04-27 10:00:00', '2025-02-06 15:53:41', 'allée du moulin de brou 01000 Bourg-en-Bresse', 110, 1, 18, '/uploads/brochures/1738853621168-Brochure_(1).pdf', 'https://www.monastere-de-brou.fr/agenda/2024/festival-alafolie'),
(83, 'Les Estivales de Brou 2024', ' Festival de musique lyrique et sacrée dans l’église du Monastère royal de Brou.', 'Du 6 au 12 juillet 2024, des concerts de musique lyrique et sacrée ont été interprétés par des artistes de renommée internationale, dans le cadre majestueux de l’église du Monastère royal de Brou.', '2024-08-07 13:00:00', '2025-02-06 16:08:05', '6 boulevard de brou 01000 Bourg-en-Bresse', 300, 1, 18, '/uploads/brochures/1738854485067-Brochure_(1).pdf', 'https://www.jds.fr/manifestations/festival/les-estivales-de-brou-2024'),
(84, 'Exposition “Trésors gothiques : l’art sacré du XIVe au XVIe siècle”', 'Une exposition exceptionnelle sur l’art gothique en Europe.', 'Du 10 février au 15 mai 2024, cette exposition a permis aux visiteurs d’explorer des chefs-d’œuvre de l’art gothique, avec des sculptures, peintures et objets liturgiques issus des plus grandes collections européennes.', '2024-02-10 14:00:00', '2025-02-06 16:09:52', '6 boulevard de brou 01000 Bourg-en-Bresse', 500, 1, 18, '/uploads/brochures/1738854592115-Brochure_(1).pdf', 'https://www.monastere-de-brou.fr/exposition-gothique-2024');
