(11, 'Credit agricole', '/uploads/partners/1733483481097-download.png', '/uploads/partners/1733483481097-images.jpg', 'https://www.credit-agricole.fr/', 'Le Crédit Agricole de Bourg-en-Bresse est une agence bancaire située à Bourg-en-Bresse, offrant une gamme de services financiers tels que la gestion de comptes, les prêts, l\'épargne et l\'assurance. Elle se concentre sur les besoins des particuliers, des professionnels et des entreprises locales, tout en promouvant des solutions adaptées à la vie économique régionale.', '2024-12-06 12:11:21', '2025-02-06 17:00:25'),
(12, 'Conservatoire de Musique', 'https://images.unsplash.com/photo-1511379938547-c1f69419868d?q=80&w=200&h=200', 'https://images.unsplash.com/photo-1514320291840-2e0a9bf2a9ae?q=80&w=1000', 'https://www.grandbourg.fr/3339-conservatoire-d-agglomeration.htm', 'Le Conservatoire de Musique est un partenaire historique des Estivales de Brou, contribuant à la formation et au développement des jeunes talents.', '2024-12-06 14:19:09', '2025-02-06 17:00:56'),
(16, 'Fondation pour les Arts', 'https://images.unsplash.com/photo-1514320291840-2e0a9bf2a9ae?q=80&w=200&h=200', 'https://images.unsplash.com/photo-1509335919466-c196457ea95a?q=80&w=1000', 'https://www.artexplora.org/', 'La Fondation pour les Arts soutient financièrement les projets innovants des Estivales de Brou.', '2024-12-06 14:19:09', '2025-02-06 16:59:59');
